namespace SlusserLabs.AnglePlates;

internal static class Boilerplate
{
    private static readonly string _version = typeof(Boilerplate).Assembly.GetName().Version.ToString(3);

    public static readonly string AutoGeneratedHeader = $"""
        // <auto-generated>
        //     This code was generated by a tool.
        //     Runtime Version: {_version}
        //
        //     Changes to this file may cause incorrect behavior and will be lost if
        //     the code is regenerated.
        // </auto-generated>
        """;

    public const string Directives = """
        #nullable enable
        """;

    public static string TemplateOptions(string accessModifier) => $$"""
        {{AutoGeneratedHeader}}

        {{Directives}}

        using AnglePlatesBuffers = global::System.Buffers;
        using AnglePlatesEncoders = global::System.Text.Encodings.Web;

        namespace SlusserLabs.AnglePlates;

        /// <summary>
        /// Controls encoding and temporary storage for generated templates.
        /// </summary>
        {{accessModifier}} class TemplateOptions
        {
            /// <summary>
            /// Gets or sets the buffer pool to use for temporary encoding.
            /// The default is <see cref="AnglePlatesBuffers.ArrayPool{char}.Shared" />.
            /// </summary>
            public AnglePlatesBuffers.ArrayPool<char> BufferPool { get; set; } = AnglePlatesBuffers.ArrayPool<char>.Shared;

            /// <summary>
            /// Gets or sets the <see cref="AnglePlatesEncoders.TextEncoder" /> to use when writing variables.
            /// The default is <see cref="AnglePlatesEncoders.HtmlEncoder.Default" />.
            /// </summary>
            /// <remarks>Set to <c>null</c> to disable expression encoding.</remarks>
            public AnglePlatesEncoders.TextEncoder? Encoder { get; set; } = AnglePlatesEncoders.HtmlEncoder.Default;

            /// <summary>
            /// Gets or sets the substitute value to use when a variable evaluates to <c>null</c>.
            /// </summary>
            /// <remarks>Setting this property to a non-empty string can be helpful when debugging templates.</remarks>
            public string? NullVariable { get; set; }
        }
        """;

    public static string TextTemplate(string accessModifier) => $$"""
        {{AutoGeneratedHeader}}

        {{Directives}}

        using global::System;
        using AnglePlatesSystem = global::System;
        using AnglePlatesBuffers = global::System.Buffers;
        using AnglePlatesIO = global::System.IO;
        using AnglePlatesCompilerServices = global::System.Runtime.CompilerServices;

        namespace SlusserLabs.AnglePlates;

        /// <summary>
        /// Base class for a text template.
        /// </summary>
        /// <typeparam name="TModel">The type of model supported by the template.</typeparam>
        {{accessModifier}} abstract class TextTemplate<TModel>
        {
            // Cap requests at 32K characters; custom pools may return larger arrays
            private const int _maxRental = 32 * 1024;
            private readonly TemplateOptions _options;

            /// <summary>
            /// Initializes a new instance of the <see cref="TextTemplate{TModel}" /> class.
            /// </summary>
            /// <param name="options">Options for controlling template processing.</param>
            protected TextTemplate(TemplateOptions options)
            {
                AnglePlatesSystem.ArgumentNullException.ThrowIfNull(options);
                _options = options;
            }

            /// <summary>
            /// Gets the <see cref="TemplateOptions" /> used to create this instance.
            /// </summary>
            public TemplateOptions Options => _options;

            /// <summary>
            /// Renders the template.
            /// </summary>
            /// <param name="model">The data model to render.</param>
            /// <param name="writer">The <see cref="AnglePlatesIO.TextWriter" /> to render the template to.</param>
            public abstract void Render(TModel model, AnglePlatesIO.TextWriter writer);

            /// <summary>
            /// Encodes the specified <paramref name="value" /> and writes it to the output.
            /// </summary>
            /// <param name="value">The string value to write.</param>
            /// <param name="writer">The template writer.</param>
            protected void Write(string? value, AnglePlatesIO.TextWriter writer)
            {
                value ??= _options.NullVariable;

                if (string.IsNullOrEmpty(value))
                {
                    return;
                }

                var encoder = _options.Encoder;
                if (encoder is null)
                {
                    WriteRaw(value, writer);
                    return;
                }

                // Widen before multiplying so large values cannot overflow before clamping
                int rentalSize = (int)AnglePlatesSystem.Math.Min((long)encoder.MaxOutputCharactersPerInputCharacter * value.Length, _maxRental);
                var pool = _options.BufferPool;
                AnglePlatesSystem.ReadOnlySpan<char> sourceChars = value.AsSpan();
                var encodedChars = pool.Rent(rentalSize);

                try
                {
                    do
                    {
                        AnglePlatesBuffers.OperationStatus status = encoder.Encode(sourceChars, encodedChars, out int charsConsumed, out int charsWritten, isFinalBlock: true);
                        switch (status)
                        {
                            case AnglePlatesBuffers.OperationStatus.NeedMoreData:
                                throw new AnglePlatesSystem.InvalidOperationException("Encoder needs more data, but all data was provided. Does this string end with an unpaired surrogate?");

                            case AnglePlatesBuffers.OperationStatus.InvalidData:
                                throw new AnglePlatesSystem.InvalidOperationException("Invalid data found in string. Does this string contain unpaired surrogates?");
                        }

                        if (charsConsumed == 0 && charsWritten == 0)
                        {
                            throw new AnglePlatesSystem.InvalidOperationException("Encoder made no progress with the temporary buffer.");
                        }

                        // Write the encoded characters and advance the source chars
                        writer.Write(encodedChars.AsSpan().Slice(0, charsWritten));
                        sourceChars = sourceChars.Slice(charsConsumed);

                        // If AnglePlatesBuffers.OperationStatus.Done, the loop will exit because sourceChars.IsEmpty
                        // If AnglePlatesBuffers.OperationStatus.DestinationTooSmall, the loop will go again because !sourceChars.IsEmpty
                    } while (!sourceChars.IsEmpty);
                }
                finally
                {
                    pool.Return(encodedChars);
                }
            }

            /// <summary>
            /// Writes the raw, unencoded specified <paramref name="value" /> to the output.
            /// </summary>
            /// <param name="value">The string value to write.</param>
            /// <param name="writer">The template writer.</param>
            [AnglePlatesCompilerServices.MethodImpl(AnglePlatesCompilerServices.MethodImplOptions.AggressiveInlining)]
            protected void WriteRaw(string? value, AnglePlatesIO.TextWriter writer)
            {
                if (!string.IsNullOrEmpty(value))
                {
                    writer.Write(value);
                }
            }
        }
        """;

    public static string Utf8Template(string accessModifier) => $$"""
        {{AutoGeneratedHeader}}

        {{Directives}}

        using global::System;
        using AnglePlatesSystem = global::System;
        using AnglePlatesBuffers = global::System.Buffers;
        using AnglePlatesCompilerServices = global::System.Runtime.CompilerServices;
        using AnglePlatesText = global::System.Text;
        using AnglePlatesPipelines = global::System.IO.Pipelines;
        using AnglePlatesThreading = global::System.Threading;
        using AnglePlatesTasks = global::System.Threading.Tasks;

        namespace SlusserLabs.AnglePlates;

        /// <summary>
        /// Base class for a UTF-8 template.
        /// </summary>
        /// <typeparam name="TModel">The type of model supported by the template.</typeparam>
        {{accessModifier}} abstract class Utf8Template<TModel>
        {
            // Cap requests at 32K characters; custom pools may return larger arrays
            private const int _maxRental = 32 * 1024;
            private readonly TemplateOptions _options;

            /// <summary>
            /// Initializes a new instance of the <see cref="Utf8Template{TModel}" /> class.
            /// </summary>
            /// <param name="options">Options for controlling template processing.</param>
            public Utf8Template(TemplateOptions options)
            {
                AnglePlatesSystem.ArgumentNullException.ThrowIfNull(options);
                _options = options;
            }

            /// <summary>
            /// Gets the <see cref="TemplateOptions" /> used to create this instance.
            /// </summary>
            public TemplateOptions Options => _options;

            /// <summary>
            /// Renders the template.
            /// </summary>
            /// <param name="model">The data model to render.</param>
            /// <param name="writer">The <see cref="AnglePlatesBuffers.IBufferWriter{byte}" /> to render the template to.</param>
            public abstract void Render(TModel model, AnglePlatesBuffers.IBufferWriter<byte> writer);

            /// <summary>
            /// Renders the template to a <see cref="AnglePlatesPipelines.PipeWriter" />.
            /// </summary>
            /// <param name="model">The data model to render.</param>
            /// <param name="writer">The <see cref="AnglePlatesPipelines.PipeWriter" /> to render the template to.</param>
            /// <param name="cancellationToken">A token to monitor for cancellation requests.</param>
            /// <returns>The result of flushing the writer.</returns>
            public AnglePlatesTasks.ValueTask<AnglePlatesPipelines.FlushResult> RenderAsync(TModel model, AnglePlatesPipelines.PipeWriter writer, AnglePlatesThreading.CancellationToken cancellationToken = default)
            {
                Render(model, writer);
                return writer.FlushAsync(cancellationToken);
            }

            /// <summary>
            /// Encodes the specified <paramref name="value" /> and writes it to the output.
            /// </summary>
            /// <param name="value">The string value to write.</param>
            /// <param name="writer">The template writer.</param>
            protected void Write(string? value, AnglePlatesBuffers.IBufferWriter<byte> writer)
            {
                value ??= _options.NullVariable;

                if (string.IsNullOrEmpty(value))
                {
                    return;
                }

                var encoder = _options.Encoder;
                if (encoder is null)
                {
                    WriteRaw(value, writer);
                    return;
                }

                // Widen before multiplying so large values cannot overflow before clamping
                int rentalSize = (int)AnglePlatesSystem.Math.Min((long)encoder.MaxOutputCharactersPerInputCharacter * value.Length, _maxRental);
                var pool = _options.BufferPool;
                AnglePlatesSystem.ReadOnlySpan<char> sourceChars = value.AsSpan();
                var encodedChars = pool.Rent(rentalSize);

                try
                {
                    do
                    {
                        AnglePlatesBuffers.OperationStatus status = encoder.Encode(sourceChars, encodedChars, out int charsConsumed, out int charsWritten, isFinalBlock: true);
                        switch (status)
                        {
                            case AnglePlatesBuffers.OperationStatus.NeedMoreData:
                                throw new AnglePlatesSystem.InvalidOperationException("Encoder needs more data, but all data was provided. Does this string end with an unpaired surrogate?");

                            case AnglePlatesBuffers.OperationStatus.InvalidData:
                                throw new AnglePlatesSystem.InvalidOperationException("Invalid data found in string. Does this string contain unpaired surrogates?");
                        }

                        if (charsConsumed == 0 && charsWritten == 0)
                        {
                            throw new AnglePlatesSystem.InvalidOperationException("Encoder made no progress with the temporary buffer.");
                        }

                        // Write the encoded characters as UTF8 and advance the source chars
                        AnglePlatesText.EncodingExtensions.GetBytes(AnglePlatesText.Encoding.UTF8, encodedChars.AsSpan().Slice(0, charsWritten), writer);
                        sourceChars = sourceChars.Slice(charsConsumed);

                        // If AnglePlatesBuffers.OperationStatus.Done, the loop will exit because sourceChars.IsEmpty
                        // If AnglePlatesBuffers.OperationStatus.DestinationTooSmall, the loop will go again because !sourceChars.IsEmpty
                    } while (!sourceChars.IsEmpty);
                }
                finally
                {
                    pool.Return(encodedChars);
                }
            }

            /// <summary>
            /// Writes the raw, unencoded specified <paramref name="value" /> to the output.
            /// </summary>
            /// <param name="value">The string value to write.</param>
            /// <param name="writer">The template writer.</param>
            [AnglePlatesCompilerServices.MethodImpl(AnglePlatesCompilerServices.MethodImplOptions.AggressiveInlining)]
            protected void WriteRaw(string? value, AnglePlatesBuffers.IBufferWriter<byte> writer)
            {
                if (!string.IsNullOrEmpty(value))
                {
                    AnglePlatesText.EncodingExtensions.GetBytes(AnglePlatesText.Encoding.UTF8, value.AsSpan(), writer);
                }
            }
        }
        """;
}
